import * as React from "react";
type SortDirection = "asc" | "desc" | null;
export interface HeaderProps {
    headers: {
        sequence: string;
        displayName: string;
        tooltipText?: string;
        align?: "left" | "right" | "center";
        width?: string;
        isEditable?: boolean;
        isEditorType?: "text" | "date" | "dropdown" | "switch";
        dropdownOptions?: {
            label: string;
            value: string;
        }[];
        isSortable?: boolean;
        sortDirection?: SortDirection;
    }[];
    onSortAction?: (sequence: string, direction: Exclude<SortDirection, null>) => void;
}
declare const Header: React.FC<HeaderProps>;
export default Header;
